solution = '''
def transform(grid):
    # Find 5-line row index
    line_row = None
    for i, row in enumerate(grid):
        if all(c == 5 for c in row):
            line_row = i
            break

    # Find column of 2s and 4s
    col_2 = None
    col_4 = None
    for c in range(9):
        has_2 = any(grid[r][c] == 2 for r in range(len(grid)))
        has_4 = any(grid[r][c] == 4 for r in range(len(grid)))
        if has_2 and col_2 is None:
            col_2 = c
        if has_4 and col_4 is None:
            col_4 = c

    # Count extension BELOW the 5-line
    ext_2 = 0
    ext_4 = 0
    for r in range(line_row + 1, len(grid)):
        if grid[r][col_2] == 2:
            ext_2 += 1
        if grid[r][col_4] == 4:
            ext_4 += 1

    # Count extension ABOVE the 5-line
    ext2_upper = 0
    ext4_upper = 0
    for r in range(0, line_row):
        if grid[r][col_2] == 2:
            ext2_upper += 1
        if grid[r][col_4] == 4:
            ext4_upper += 1

    # Rule: winner is longer extension below; on tie, shorter upper wins
    if ext_2 > ext_4:
        return [[2, 2], [2, 2]]
    elif ext_4 > ext_2:
        return [[4, 4], [4, 4]]
    else:
        # Extension below tied - shorter upper wins
        if ext2_upper < ext4_upper:
            return [[2, 2], [2, 2]]
        elif ext4_upper < ext2_upper:
            return [[4, 4], [4, 4]]
        else:
            # Both tied - 2s win as default
            return [[2, 2], [2, 2]]
'''

